import React from 'react'
import { Dialog, DialogTitle, DialogContent, Button, Grid } from '@mui/material'

const PromotionModal = ({ onSelectPiece }) => {
  const pieces = ['q', 'r', 'b', 'n'] // Queen, Rook, Bishop, Knight

  return (
    <Dialog open={true} onClose={() => onSelectPiece('q')}>
      <DialogTitle>Select Promotion Piece</DialogTitle>
      <DialogContent>
        <Grid container spacing={2} justifyContent="center">
          {pieces.map((piece) => (
            <Grid item key={piece}>
              <Button variant="contained" onClick={() => onSelectPiece(piece)}>
                {piece.toUpperCase()}
              </Button>
            </Grid>
          ))}
        </Grid>
      </DialogContent>
    </Dialog>
  )
}

export default PromotionModal
