// Hook to manage Stockfish engine
const useStockfish = () => {
  const stockfish = useRef(null)

  useEffect(() => {
    stockfish.current = new Worker(
      `${process.env.PUBLIC_URL}/js/stockfish-17-lite-single.js`
    )
    return () => {
      if (stockfish.current) {
        stockfish.current.terminate()
      }
    }
  }, [])

  return stockfish
}

// Chess Game Component
const ChessGame = () => {
  const initialState = {
    game: new Chess(),
    moveHistory: [new Chess().fen()],
    currentMoveIndex: 0,
    bestMove: '',
    evaluation: '',
    promotionSquare: null,
    promotionSource: null,
    showPromotionModal: false,
    pieceStyle: 'cburnett', // Default style
    isPvS: true,
    playerColor: 'w',
    blunderSuggestion: false,
  }

  const chessReducer = (state, action) => {
    switch (action.type) {
      case 'MOVE':
        return {
          ...state,
          game: action.payload.game,
          moveHistory: [
            ...state.moveHistory.slice(0, state.currentMoveIndex + 1),
            action.payload.fen,
          ],
          currentMoveIndex: state.currentMoveIndex + 1,
        }
      case 'UNDO':
        return state.currentMoveIndex > 0
          ? {
              ...state,
              currentMoveIndex: state.currentMoveIndex - 1,
              game: new Chess(state.moveHistory[state.currentMoveIndex - 1]),
            }
          : state
      case 'REDO':
        return state.currentMoveIndex < state.moveHistory.length - 1
          ? {
              ...state,
              currentMoveIndex: state.currentMoveIndex + 1,
              game: new Chess(state.moveHistory[state.currentMoveIndex + 1]),
            }
          : state
      case 'RESET':
        return initialState
      case 'SET_PIECE_STYLE':
        return {
          ...state,
          pieceStyle: action.payload,
        }
      case 'SET_PLAYER_COLOR':
        return {
          ...state,
          playerColor: action.payload,
        }
      case 'SET_SHOW_PROMOTION_MODAL':
        return {
          ...state,
          showPromotionModal: action.payload,
        }
      case 'SET_PROMOTION_SOURCE':
        return {
          ...state,
          promotionSource: action.payload,
        }
      case 'SET_PROMOTION_SQUARE':
        return {
          ...state,
          promotionSquare: action.payload,
        }
      case 'SET_BEST_MOVE':
        return {
          ...state,
          bestMove: action.payload,
        }
      case 'SET_EVALUATION':
        return {
          ...state,
          evaluation: action.payload,
        }
      case 'TOGGLE_PV_PV_S':
        return {
          ...state,
          isPvS: !state.isPvS,
        }
      case 'SET_BLUNDER_SUGGESTION':
        return {
          ...state,
          blunderSuggestion: action.payload,
        }
      default:
        return state
    }
  }

  const [state, dispatch] = useReducer(chessReducer, initialState)
  const {
    game,
    bestMove,
    evaluation,
    promotionSquare,
    promotionSource,
    showPromotionModal,
    pieceStyle,
    isPvS,
    playerColor,
    blunderSuggestion,
  } = state
  const stockfish = useStockfish()

  const requestStockfishMove = () => {
    if (!stockfish.current) return

    try {
      stockfish.current.postMessage(`position fen ${game.fen()}`)
      stockfish.current.postMessage('go depth 12')

      stockfish.current.onmessage = (event) => {
        const message = event.data
        if (message.startsWith('bestmove')) {
          const bestMove = message.split(' ')[1]
          const gameCopy = new Chess(game.fen())
          gameCopy.move(bestMove)
          dispatch({
            type: 'MOVE',
            payload: { game: gameCopy, fen: gameCopy.fen() },
          })
          dispatch({ type: 'SET_BEST_MOVE', payload: bestMove })
        } else if (message.includes('info depth 12')) {
          const parts = message.split(' ')
          const scoreIndex = parts.indexOf('score') + 2
          if (parts[scoreIndex - 1] === 'cp') {
            let score = parseInt(parts[scoreIndex], 10)
            if (game.turn() === 'w') score = -score
            dispatch({
              type: 'SET_EVALUATION',
              payload: `${(score / 100).toFixed(2)}`,
            })
            // Detect blunder
            if (score < -300) {
              dispatch({
                type: 'SET_BLUNDER_SUGGESTION',
                payload: true,
              })
            }
          } else if (parts[scoreIndex - 1] === 'mate') {
            const mateIn = parseInt(parts[scoreIndex], 10)
            dispatch({
              type: 'SET_EVALUATION',
              payload: `Mate in ${Math.abs(mateIn)}`,
            })
          }
        }
      }
    } catch (error) {
      console.error('Stockfish error:', error)
    }
  }

  const handleBlunderSuggestion = () => {
    dispatch({ type: 'UNDO' })
    requestStockfishMove()
  }

  const isPromotionMove = (from, to) => {
    const piece = game.get(from)
    return (
      piece?.type === 'p' &&
      ((piece.color === 'w' && to[1] === '8') ||
        (piece.color === 'b' && to[1] === '1'))
    )
  }

  const handlePromotionSelection = (piece) => {
    if (!promotionSource || !promotionSquare) return

    const gameCopy = new Chess(game.fen())
    gameCopy.move({
      from: promotionSource,
      to: promotionSquare,
      promotion: piece,
    })

    dispatch({ type: 'MOVE', payload: { game: gameCopy, fen: gameCopy.fen() } })
    dispatch({ type: 'SET_SHOW_PROMOTION_MODAL', payload: false })
  }

  const handleMove = (source, target) => {
    if (isPromotionMove(source, target)) {
      dispatch({ type: 'SET_PROMOTION_SOURCE', payload: source })
      dispatch({ type: 'SET_PROMOTION_SQUARE', payload: target })
      dispatch({ type: 'SET_SHOW_PROMOTION_MODAL', payload: true })
      return false
    }

    const gameCopy = new Chess(game.fen())
    const move = gameCopy.move({ from: source, to: target })
    if (!move) {
      alert('Invalid Move!')
      return false
    }

    dispatch({ type: 'MOVE', payload: { game: gameCopy, fen: gameCopy.fen() } })
    if (isPvS) {
      requestStockfishMove()
    }
    return true
  }

  const resetGame = (color = 'w') => {
    dispatch({ type: 'RESET' })
    dispatch({ type: 'SET_PLAYER_COLOR', payload: color })
    if (color === 'b') {
      requestStockfishMove()
    }
  }

  const handleUndo = () => {
    dispatch({ type: 'UNDO' })
  }

  const handleRedo = () => {
    dispatch({ type: 'REDO' })
  }

  useEffect(() => {
    const label = document.getElementById('piece-style-label')
    if (!label) return

    const parent = label.parentElement
    if (parent) {
      parent.style.display = 'block'
      parent.style.paddingTop = '30px' // Pushes the next sibling down
    }
  }, [pieceStyle])

  const customPieces = useMemo(() => getCustomPieces(pieceStyle), [pieceStyle])

  return (
    <Container>
      <Typography variant="h4">Chess Game with Stockfish</Typography>
      <Box sx={{ mb: 2, display: 'flex', gap: 2 }}>
        <Button variant="contained" onClick={resetGame}>
          Reset Game
        </Button>
        <Button variant="contained" onClick={requestStockfishMove}>
          Stockfish Move
        </Button>
      </Box>
      <Box sx={{ mb: 2 }}>
        <FormControl variant="outlined" fullWidth>
          <InputLabel id="piece-style-label" htmlFor="piece-style-select">
            Piece Style
          </InputLabel>
          <Select
            labelId="piece-style-label"
            id="piece-style-select"
            name="piece-style"
            value={pieceStyle}
            onChange={(e) =>
              dispatch({ type: 'SET_PIECE_STYLE', payload: e.target.value })
            }
            label="Piece Style"
          >
            {chessStyles.map((style) => (
              <MenuItem key={style} value={style}>
                {style}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </Box>
      <ChessControls
        resetGame={resetGame}
        handleUndo={handleUndo}
        handleRedo={handleRedo}
        isPvS={isPvS}
        togglePvPvsPvS={() => {
          dispatch({ type: 'TOGGLE_PV_PV_S' })
          if (!isPvS && playerColor === 'b') {
            requestStockfishMove()
          }
        }}
      />
      <Chessboard
        position={game.fen()}
        onPieceDrop={handleMove}
        boardOrientation={playerColor === 'w' ? 'white' : 'black'}
        customPieces={customPieces}
        boardWidth={500}
      />
      <GameInfo bestMove={bestMove} evaluation={evaluation} />
      {showPromotionModal && (
        <PromotionModal onSelectPiece={handlePromotionSelection} />
      )}
      {blunderSuggestion && (
        <Box sx={{ mb: 2, display: 'flex', gap: 2 }}>
          <Button
            variant="contained"
            color="error"
            onClick={handleBlunderSuggestion}
          >
            Undo Blunder
          </Button>
          <Button
            variant="contained"
            onClick={() =>
              dispatch({ type: 'SET_BLUNDER_SUGGESTION', payload: false })
            }
          >
            Ignore Suggestion
          </Button>
        </Box>
      )}
    </Container>
  )
}

export default ChessGame
