import React from 'react'
import { Button, Box, Tooltip } from '@mui/material'

const ChessControls = ({
  resetGame,
  handleUndo,
  handleRedo,
  isPvS,
  togglePvPvsPvS,
}) => {
  return (
    <Box sx={{ mb: 2, display: 'flex', gap: 2, justifyContent: 'center' }}>
      <Tooltip title="Start a new game as White">
        <Button
          variant="contained"
          color="primary"
          onClick={() => resetGame('w')}
        >
          Play as White
        </Button>
      </Tooltip>
      <Tooltip title="Start a new game as Black">
        <Button
          variant="contained"
          color="secondary"
          onClick={() => resetGame('b')}
        >
          Play as Black
        </Button>
      </Tooltip>
      <Tooltip title="Undo the last move">
        <Button variant="contained" color="warning" onClick={handleUndo}>
          Undo Move
        </Button>
      </Tooltip>
      <Tooltip title="Redo the previous move">
        <Button variant="contained" color="info" onClick={handleRedo}>
          Redo Move
        </Button>
      </Tooltip>
      <Tooltip title="Toggle Player vs Stockfish">
        <Button variant="contained" color="success" onClick={togglePvPvsPvS}>
          {isPvS ? 'Switch to PvP' : 'Switch to PvS'}
        </Button>
      </Tooltip>
    </Box>
  )
}

export default ChessControls
