import React from 'react'
import { Typography, Box, Divider } from '@mui/material'
import ThreatMeter from './ThreatMeter'
import MateInstructions from './MateInstructions'

const GameInfo = ({ bestMove, evaluation }) => {
  return (
    <Box sx={{ mt: 2, p: 2, border: '1px solid #ddd', borderRadius: 2 }}>
      <Typography variant="h6">
        Best Move: {bestMove || 'Calculating...'}
      </Typography>
      <Divider sx={{ my: 1 }} />
      {evaluation ? (
        <>
          <ThreatMeter evaluation={evaluation} />
          {evaluation.includes('Mate') && (
            <MateInstructions mateInfo={{ evaluation }} />
          )}
        </>
      ) : (
        <Typography variant="body2" color="textSecondary">
          No evaluation available
        </Typography>
      )}
    </Box>
  )
}

export default GameInfo
